-- Run this non-destructive migration against the database configured by DB_NAME.
CREATE TABLE IF NOT EXISTS drivers (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL UNIQUE, vehicle_number VARCHAR(30), license_number VARCHAR(60), assigned_area VARCHAR(120), driver_status ENUM('Available','On Route','On Break','Completed','Offline') NOT NULL DEFAULT 'Available', FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS garbage_bins (id INT AUTO_INCREMENT PRIMARY KEY, bin_code VARCHAR(30) NOT NULL UNIQUE, location VARCHAR(180) NOT NULL, latitude DECIMAL(10,7), longitude DECIMAL(10,7), capacity INT DEFAULT 120, current_level INT DEFAULT 0, bin_type VARCHAR(60) DEFAULT 'General Waste', status ENUM('Pending','In Progress','Completed','Skipped','Normal','Almost Full','Full') NOT NULL DEFAULT 'Pending', priority ENUM('Normal','High','Urgent') NOT NULL DEFAULT 'Normal', assigned_driver_id INT NULL, route_order INT DEFAULT 0, last_collection DATETIME NULL, FOREIGN KEY (assigned_driver_id) REFERENCES drivers(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS driver_locations (id INT AUTO_INCREMENT PRIMARY KEY, driver_id INT NOT NULL, latitude DECIMAL(10,7) NOT NULL, longitude DECIMAL(10,7) NOT NULL, recorded_at DATETIME NOT NULL, INDEX(driver_id, recorded_at), FOREIGN KEY (driver_id) REFERENCES drivers(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS collection_history (id INT AUTO_INCREMENT PRIMARY KEY, driver_id INT NOT NULL, bin_id INT NOT NULL, waste_collected DECIMAL(8,2) DEFAULT 0, status ENUM('Completed','Skipped') NOT NULL, skip_reason VARCHAR(300), collected_at DATETIME NOT NULL, INDEX(driver_id, collected_at), FOREIGN KEY (driver_id) REFERENCES drivers(id), FOREIGN KEY (bin_id) REFERENCES garbage_bins(id));
CREATE TABLE IF NOT EXISTS collection_requests (id INT AUTO_INCREMENT PRIMARY KEY, bin_id INT NULL, status ENUM('Pending','Assigned','In Progress','Completed','Cancelled') DEFAULT 'Pending', FOREIGN KEY (bin_id) REFERENCES garbage_bins(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS complaints (id INT AUTO_INCREMENT PRIMARY KEY, driver_id INT NULL, category VARCHAR(60) NOT NULL, description TEXT NOT NULL, location VARCHAR(180) NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'Open', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (driver_id) REFERENCES drivers(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS notifications (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, message VARCHAR(500) NOT NULL, type VARCHAR(30) DEFAULT 'info', is_read BOOLEAN DEFAULT FALSE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(user_id, is_read), FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE);
